{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbf9;--ink:#102a2a;--muted:#536a6a;--accent:#7fb77e;--card:#ffffff}
    *{box-sizing:border-box}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px}
    .brand{font-weight:600;letter-spacing:.6px}
    nav a{color:var(--ink);text-decoration:none;margin:0 10px;font-size:14px}
    .wrap{max-width:980px;margin:28px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;background:linear-gradient(180deg,rgba(127,183,126,.06),transparent);padding:28px;border-radius:12px}
    .hero h1{margin:0;font-size:28px}
    .hero p{margin:6px 0;color:var(--muted)}
    .meta{display:flex;gap:12px;align-items:center}
    .pillars{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:18px}
    .card{background:var(--card);padding:16px;border-radius:10px;box-shadow:0 6px 18px rgba(10,10,12,.04)}
    .muted{color:var(--muted);font-size:14px}
    .myth-list{display:grid;gap:10px;margin-top:12px}
    .myth{display:flex;gap:12px;align-items:flex-start}
    .mark{width:40px;height:40px;border-radius:8px;background:rgba(127,183,126,.12);display:flex;align-items:center;justify-content:center;color:var(--accent);font-weight:700}
    footer{padding:26px 28px;text-align:center;color:var(--muted);font-size:13px}
    .cta{display:inline-block;padding:10px 14px;border-radius:8px;background:var(--accent);color:white;text-decoration:none;margin-top:12px}
    .case-list{display:grid;gap:12px}
    .case-note{font-size:15px}
    /* subtle svg pattern as background */
    .pattern{position:fixed;right:-120px;top:-120px;width:380px;height:380px;opacity:.06;pointer-events:none}
    @media(min-width:880px){.hero{grid-template-columns:1fr 320px}}
  </style>
</head>
<body>
  <svg class="pattern" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" aria-hidden>
    <defs>
      <pattern id="p" width="10" height="10" patternUnits="userSpaceOnUse" patternTransform="rotate(22)">
        <rect width="6" height="6" fill="#77b07a" rx="1"/>
        <circle cx="8" cy="2" r="1" fill="#9fd3a3" />
      </pattern>
    </defs>
    <rect width="100" height="100" fill="url(#p)" />
  </svg>

  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Story</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Plans</a>
      <a href="contact.html">Hello</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero card">
      <div>
        <h1>Guidance for steady days, shaped to your life</h1>
        <p class="muted">We build small rituals that become the frame for clearer thinking, kinder energy, and reliable momentum. No fads — just practical scaffolding for your rhythms.</p>
        <div style="margin-top:12px">
          <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <span style="margin-left:12px;color:var(--muted);font-size:14px">or call <a href="tel:{{PHONE}}">{{PHONE}}</a></span>
        </div>
      </div>
      <aside>
        <div class="card muted">
          <strong>Who I work with</strong>
          <p style="margin:8px 0">People wanting reliable practices—not quick fixes—who value clarity over perfection.</p>
          <div style="font-size:13px;color:var(--muted)">Sessions in {{CITY}}, {{STATE}} &amp; remote.</div>
        </div>
      </aside>
    </section>

    <section style="margin-top:20px">
      <div class="pillars">
        <div class="card">
          <strong>Foundations</strong>
          <p class="muted">A small set of repeatable moves you can do anywhere: morning alignments, mid-day resets, evening reflections.</p>
        </div>
        <div class="card">
          <strong>Design</strong>
          <p class="muted">We craft sequences that fit your energy and schedule, not the other way around.</p>
        </div>
        <div class="card">
          <strong>Measure</strong>
          <p class="muted">Clear micro-goals that make progress visible without pressure.</p>
        </div>
      </div>
    </section>

    <section style="margin-top:22px">
      <div class="card">
        <strong>Myths I meet</strong>
        <div class="myth-list">
          <div class="myth"><div class="mark">1</div><div><strong>Myth:</strong> You need dramatic upheaval to change.
            <div class="muted">Truth: Small sequence tweaks stack into steady momentum.</div></div></div>
          <div class="myth"><div class="mark">2</div><div><strong>Myth:</strong> Routines must feel rigid.
            <div class="muted">Truth: Gentle constraints can free attention, not choke it.</div></div></div>
          <div class="myth"><div class="mark">3</div><div><strong>Myth:</strong> If it’s simple, it’s not meaningful.
            <div class="muted">Truth: Simple practices are often the most sustainable.</div></div></div>
        </div>
      </div>
    </section>

    <section style="margin-top:22px">
      <div class="card">
        <strong>Selected notes — real outcomes</strong>
        <div class="case-list" style="margin-top:10px">
          <div class="case-note"><em>"A 10-minute evening ritual reduced decision fog and made mornings easier."</em> — client, creative professional</div>
          <div class="case-note"><em>"We mapped a week that fits my work rhythm; now the week feels like a resource."</em> — client, educator</div>
        </div>
      </div>
    </section>

    <section style="margin-top:22px">
      <div class="card">
        <strong>Still curious?</strong>
        <p class="muted">Book a short call to describe your days. We’ll sketch a light, testable plan together.</p>
        <a class="cta" href="book.html">Start with a conversation</a>
      </div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — {{TAGLINE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffefc;--ink:#153233;--muted:#5a6f6f;--accent:#6aa96a}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 22px}
    nav a{margin:0 8px;text-decoration:none;color:var(--ink);font-size:14px}
    .wrap{max-width:980px;margin:20px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:#fff;padding:16px;border-radius:10px;box-shadow:0 6px 20px rgba(12,14,12,.04)}
    h1{margin:0 0 8px 0}
    .muted{color:var(--muted)}
    .service{padding:12px;border-radius:8px;margin-bottom:10px;border:1px solid rgba(86,111,86,.06)}
    .service h3{margin:0 0 6px 0}
    .actions{display:flex;gap:8px;margin-top:10px}
    .btn{padding:8px 10px;border-radius:8px;text-decoration:none;color:white;background:var(--accent)}
    /* habit builder */
    .hb{margin-top:12px}
    form{display:flex;flex-direction:column;gap:8px}
    input,select{padding:8px;border-radius:8px;border:1px solid #e6e8e6}
    .checklist{margin-top:14px}
    .print-area{padding:12px;border-radius:8px;border:1px dashed rgba(86,111,86,.12);background:linear-gradient(180deg,rgba(106,169,106,.03),transparent)}
    /* modal */
    .modal{position:fixed;left:0;top:0;width:100%;height:100%;display:none;align-items:center;justify-content:center;background:rgba(6,8,6,.36)}
    .modal .box{background:white;padding:20px;border-radius:12px;max-width:520px;width:94%}
    .modal.show{display:flex}
    .breath-circle{width:140px;height:140px;border-radius:50%;margin:10px auto;background:radial-gradient(circle at 30% 30%,#9fe2a6 0,#7fb77e 50%,#6aa96a 100%);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    .timer{font-size:20px;text-align:center;color:var(--muted)}
    .small{font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:600">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Story</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Plans</a>
      <a href="contact.html">Hello</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="grid">
      <div>
        <div class="card">
          <h1>Offerings tuned to practice</h1>
          <p class="muted">Short pathways and ongoing structures—both guided to shape habit and light enough to keep.</p>

          <div class="service">
            <h3>Harmony Sessions — single</h3>
            <div class="muted">A focused 50-minute session to map a week of practical moves and an anchor ritual.</div>
            <div class="actions">
              <a class="btn" href="book.html">Reserve a session</a>
              <button class="btn" style="background:#3b9b56" onclick="openExercise('breathing')">Try a breathing reset</button>
            </div>
          </div>

          <div class="service">
            <h3>Steady Course — 6 weeks</h3>
            <div class="muted">Six weekly check-ins, small experiments, and a habit map you keep. Hybrid coaching + hands-on guides.</div>
            <div class="actions">
              <a class="btn" href="programs.html#steady">See plan</a>
              <button class="btn" style="background:#3b9b56" onclick="openExercise('journaling')">Try a journaling prompt</button>
            </div>
          </div>

          <div class="service">
            <h3>Practice Sprint — 4 weeks</h3>
            <div class="muted">A short, focused sprint: pick one habit. Daily micro-checks and two coaching calls.</div>
            <div class="actions"><a class="btn" href="programs.html#sprint">Learn more</a></div>
          </div>

        </div>

        <div class="card hb" aria-live="polite">
          <h2>7‑Day Challenge generator</h2>
          <p class="muted">Create a tiny, testable challenge and print a checklist to carry through the week.</p>
          <form id="hb-form">
            <label><span class="small">Goal (short)</span>
              <input id="hb-goal" placeholder="e.g., 5 minutes evening reflection" required />
            </label>
            <label><span class="small">Start date</span>
              <input id="hb-date" type="date" />
            </label>
            <label><span class="small">Daily cue</span>
              <select id="hb-cue">
                <option>After breakfast</option>
                <option>Before bed</option>
                <option>Midday pause</option>
                <option>Right after work</option>
              </select>
            </label>
            <div style="display:flex;gap:8px;align-items:center">
              <button type="submit" class="btn">Generate checklist</button>
              <button type="button" onclick="randomizeGoal()" style="background:#888;color:#fff;padding:8px;border-radius:8px;border:none">Suggest</button>
            </div>
          </form>

          <div id="checklist" class="checklist" style="display:none">
            <div class="print-area" id="printable">
              <h3 id="print-title"></h3>
              <div id="print-meta" class="small muted"></div>
              <ol id="days"></ol>
            </div>
            <div style="margin-top:10px;display:flex;gap:8px">
              <button class="btn" onclick="window.print()">Print checklist</button>
              <button class="btn" style="background:#5a6f6f" onclick="resetHB()">Start over</button>
            </div>
          </div>
        </div>

      </div>

      <aside>
        <div class="card">
          <strong>Quick try</strong>
          <p class="muted">Tap a practice below to experience a brief guided reset. No signup required.</p>
          <div style="display:flex;flex-direction:column;gap:8px;margin-top:12px">
            <button class="btn" onclick="openExercise('breathing')">Try breathing (1 min)</button>
            <button class="btn" style="background:#3b9b56" onclick="openExercise('journaling')">Try journaling (3 min)</button>
            <button class="btn" style="background:#2f8a4a" onclick="openExercise('intention')">Set an intention (1 min)</button>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <strong>Contact</strong>
          <p class="muted">Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        </div>
      </aside>

    </section>
  </main>

  <div id="exercise-modal" class="modal" role="dialog" aria-hidden="true">
    <div class="box" id="modal-box">
      <button onclick="closeExercise()" style="float:right;background:none;border:none;font-size:16px">✕</button>
      <div id="exercise-content"></div>
    </div>
  </div>

  <script>
    // Habit builder logic
    const form = document.getElementById('hb-form');
    const checklist = document.getElementById('checklist');
    const daysOl = document.getElementById('days');
    const printTitle = document.getElementById('print-title');
    const printMeta = document.getElementById('print-meta');

    function formatDate(d){return d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}

    form.addEventListener('submit', (e)=>{
      e.preventDefault();
      const goal = document.getElementById('hb-goal').value.trim();
      const cue = document.getElementById('hb-cue').value;
      let start = document.getElementById('hb-date').value ? new Date(document.getElementById('hb-date').value) : new Date();
      daysOl.innerHTML = '';
      printTitle.textContent = '7‑Day Challenge — ' + goal;
      printMeta.textContent = cue + ' • start: ' + formatDate(start);
      for(let i=0;i<7;i++){
        const li = document.createElement('li');
        const date = new Date(start);
        date.setDate(start.getDate()+i);
        li.innerHTML = `<label style="display:flex;gap:10px;align-items:center"><input type=checkbox data-day="${i}"/> <span style="flex:1">${formatDate(date)} — ${goal}</span></label>`;
        daysOl.appendChild(li);
      }
      checklist.style.display = 'block';
      window.location.hash = '#checklist';
    });

    function randomizeGoal(){
      const samples = ['3 minute breathing','Evening reflection: 5 mins','One page of journaling','Two-minute walk after lunch','Set three intentions for the day'];
      document.getElementById('hb-goal').value = samples[Math.floor(Math.random()*samples.length)];
    }
    function resetHB(){document.getElementById('hb-goal').value='';document.getElementById('hb-date').value='';document.getElementById('hb-cue').selectedIndex=0;checklist.style.display='none';daysOl.innerHTML='';}

    // Guided exercise modal
    const modal = document.getElementById('exercise-modal');
    const content = document.getElementById('exercise-content');
    let intervalRef = null;

    function openExercise(type){
      buildExercise(type);
      modal.classList.add('show');
      modal.setAttribute('aria-hidden','false');
    }
    function closeExercise(){
      modal.classList.remove('show');
      modal.setAttribute('aria-hidden','true');
      if(intervalRef) clearInterval(intervalRef);
    }

    function buildExercise(type){
      if(intervalRef) clearInterval(intervalRef);
      if(type==='breathing'){
        content.innerHTML = `
          <h2>Breathe: simple 60s reset</h2>
          <div class="breath-circle" id="circle">Inhale</div>
          <div class="timer" id="b-timer">60</div>
          <p class="small">Follow the expansion: inhale for 4s, hold 4s, exhale 6s. Repeat until time ends.</p>
        `;
        let t = 60; const circle = document.getElementById('circle'); const timer = document.getElementById('b-timer');
        const phases = ['Inhale','Hold','Exhale']; let phaseIndex=0; let phaseTime=4; let phaseCounter=0; 
        intervalRef = setInterval(()=>{
          t--; timer.textContent = t;
          phaseCounter++;
          if(phaseIndex===2){ // exhale phase should be 6s
            if(phaseCounter>=6){phaseIndex=0;phaseCounter=0}
          } else {
            if(phaseCounter>=4){phaseIndex++;phaseCounter=0}
          }
          circle.textContent = phases[phaseIndex];
          const scale = phaseIndex===0 ? 1 + (phaseCounter/4)*0.28 : phaseIndex===1 ? 1.28 : 1.28 - (phaseCounter/(phaseIndex===2?6:4))*0.28;
          circle.style.transform = `scale(${scale})`;
          if(t<=0){clearInterval(intervalRef);timer.textContent='Done';setTimeout(()=>closeExercise(),900)}
        },1000);
      } else if(type==='journaling'){
        content.innerHTML = `
          <h2>Three-minute free-write</h2>
          <p class="small">A short prompt. Start writing without judgment. We’ll time 3 minutes.</p>
          <div style="margin-top:8px"><strong>Prompt:</strong> What small change today would make tomorrow kinder to you?</div>
          <textarea id="j-input" style="width:100%;height:140px;margin-top:8px;padding:10px;border-radius:8px;border:1px solid #eee"></textarea>
          <div class="timer" id="j-timer">180</div>
          <div style="margin-top:8px"><button class="btn" onclick="finishJournaling()">Finish early</button></div>
        `;
        let t=180; const timer = document.getElementById('j-timer');
        intervalRef = setInterval(()=>{t--; timer.textContent = t; if(t<=0){clearInterval(intervalRef);timer.textContent='End';setTimeout(()=>closeExercise(),900)}},1000);
      } else if(type==='intention'){
        content.innerHTML = `
          <h2>Set an intention</h2>
          <p class="small">One clear line that guides the next few hours.</p>
          <input id="i-text" style="width:100%;padding:10px;border-radius:8px;border:1px solid #eee" placeholder="I will..." />
          <div style="margin-top:12px;display:flex;justify-content:space-between;align-items:center">
            <div class="small">Take 40 seconds to breathe and repeat it once.</div>
            <button class="btn" onclick="saveIntention()">Save</button>
          </div>
        `;
      }
    }
    function finishJournaling(){ if(intervalRef) clearInterval(intervalRef); closeExercise(); }
    function saveIntention(){ const val = document.getElementById('i-text').value; if(val.trim()){alert('Intention saved: '+val); } closeExercise(); }

    // close on backdrop click
    modal.addEventListener('click', (e)=>{ if(e.target===modal) closeExercise(); });
  </script>
</body>
</html>"} 
{"path":"programs.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Plans — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfdfc;--ink:#0f2b2b;--muted:#556868;--accent:#7bb67b}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:var(--ink)}
