      modal.style.display='flex'; modal.setAttribute('aria-hidden','false');
    }
    function closeExercise(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); if(intervalRef) clearInterval(intervalRef); }

    function buildExercise(type){
      if(intervalRef) clearInterval(intervalRef);
      if(type==='breathing'){
        content.innerHTML = `
          <h2>Breathe — quick minute</h2>
          <div style="width:120px;height:120px;border-radius:50%;margin:12px auto;background:linear-gradient(180deg,#9fe2a6,#6aa96a);display:flex;align-items:center;justify-content:center;color:white;font-weight:700" id="c">Inhale</div>
